import{_ as t,o,c as i,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Tech Talk: Making Teuthology Friendly","description":"","frontmatter":{"title":"Ceph Tech Talk: Making Teuthology Friendly","date":"2023-08-16T00:00:00.000Z","updated":"2023-08-17T00:00:00.000Z","tags":["Ceph","Teuthology","User Interface","Automation","Testing Framework"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Tech_Talk_-_Making_Teuthology_Friendly.md","filePath":"posts/2023/Ceph_Tech_Talk_-_Making_Teuthology_Friendly.md","lastUpdated":1780459816000}'),n={name:"posts/2023/Ceph_Tech_Talk_-_Making_Teuthology_Friendly.md"};function r(s,l,p,g,a,u){return o(),i("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph 项目中使用 Teuthology 测试框架的改进</p><p><strong>主讲人：</strong> Devansh，Google Summer of Code 实习生，SEF 项目成员</p><p><strong>会议时间：</strong> [具体日期]</p><p><strong>会议地点：</strong> [具体地点]</p><p><strong>参会人员：</strong> [列出参会人员]</p><p><strong>会议内容：</strong></p><ol><li><p><strong>项目介绍：</strong></p><ul><li>Teuthology 是一个用于安全测试的 Python 框架，用于在远程主机上通过 SSH 运行测试。</li><li>Pulpito 是一个用于监控 Teuthology 测试基础设施的 Web 仪表板，包括测试队列和可用测试节点。</li></ul></li><li><p><strong>现有问题：</strong></p><ul><li>Teuthology 的命令行界面（CLI）复杂，对新用户不友好。</li><li>用户需要手动配置多个参数，如仓库 URL、分支名称和套件选项，容易导致错误。</li><li>新用户难以发现和理解可用命令、选项及其含义，导致使用困难。</li></ul></li><li><p><strong>解决方案：</strong></p><ul><li>开发下一代 Pulpito，提供更直观的用户界面，允许用户通过仪表板直接调度或终止作业。</li><li>实现了一个 Teuthology API，并与下一代 Pulpito 集成，使用户无需 SSH 进入服务器即可管理作业。</li></ul></li><li><p><strong>实施细节：</strong></p><ul><li>主要功能包括 GitHub 认证、作业调度和作业终止。</li><li>通过仪表板，用户可以轻松配置和监控测试，提高团队生产力。</li></ul></li><li><p><strong>演示：</strong></p><ul><li>展示了如何通过下一代 Pulpito 界面调度作业和终止作业。</li><li>演示了作业调度的实时反馈和错误处理的流程。</li></ul></li><li><p><strong>未来展望：</strong></p><ul><li>考虑将 Paddles 服务迁移到 FastAPI，以利用其社区支持和内置功能。</li><li>改进下一代 Pulpito 的用户体验，增加更多用户中心的功能，如作业历史记录和错误日志展示。</li></ul></li><li><p><strong>感谢与反馈：</strong></p><ul><li>感谢导师 Zach、Aishwarya 和 Junior 在整个项目过程中的帮助。</li><li>欢迎与会者提供反馈和建议，以进一步改进项目。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>继续完善下一代 Pulpito 的功能。</li><li>探索将常用命令存储在数据库中的可能性。</li><li>增强错误日志的展示方式，提供更结构化的错误信息。</li></ul><p><strong>会议结束语：</strong></p><ul><li>感谢所有参与者的参与和反馈，期待继续改进和贡献于 SEF 项目。</li></ul><p><strong>附件：</strong></p><ul><li>演示视频链接</li><li>项目 GitHub 仓库链接</li></ul><p><strong>会议记录人：</strong> [记录人姓名]</p><p><strong>审核人：</strong> [审核人姓名]</p><p><strong>日期：</strong> [记录日期]</p>',17)])])}const T=t(n,[["render",r]]);export{h as __pageData,T as default};
